{"metadata":{"kernelspec":{"language":"python","display_name":"Python 3","name":"python3"},"language_info":{"name":"python","version":"3.12.13","mimetype":"text/x-python","codemirror_mode":{"name":"ipython","version":3},"pygments_lexer":"ipython3","nbconvert_exporter":"python","file_extension":".py"},"kaggle":{"accelerator":"nvidiaTeslaT4","dataSources":[{"sourceType":"competition","sourceId":143716},{"sourceType":"modelInstanceVersion","sourceId":928968},{"sourceType":"modelInstanceVersion","sourceId":928961},{"sourceType":"modelInstanceVersion","sourceId":928965},{"sourceType":"modelInstanceVersion","sourceId":928960}],"isInternetEnabled":true,"language":"python","sourceType":"script","isGpuEnabled":false}},"nbformat_minor":4,"nbformat":4,"cells":[{"cell_type":"code","source":"# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-07-08T09:08:07.156473Z\",\"iopub.execute_input\":\"2026-07-08T09:08:07.157172Z\",\"iopub.status.idle\":\"2026-07-08T09:08:13.442200Z\",\"shell.execute_reply.started\":\"2026-07-08T09:08:07.157136Z\",\"shell.execute_reply\":\"2026-07-08T09:08:13.439836Z\"},\"jupyter\":{\"outputs_hidden\":false}}\n# This Python 3 environment comes with many helpful analytics libraries installed\n# It is defined by the kaggle/python Docker image: https://github.com/kaggle/docker-python\n# For example, here's several helpful packages to load\n\nimport numpy as np # linear algebra\nimport pandas as pd # data processing, CSV file I/O (e.g. pd.read_csv)\n\n# Input data files are available in the read-only \"../input/\" directory\n# For example, running this (by clicking run or pressing Shift+Enter) will list all files under the input directory\n\nimport os\nfor dirname, _, filenames in os.walk('/kaggle/input'):\n    for filename in filenames:\n        print(os.path.join(dirname, filename))\n\n# You can write up to 20GB to the current directory (/kaggle/working/) that gets preserved as output when you create a version using \"Save & Run All\" \n# You can also write temporary files to /kaggle/temp/, but they won't be saved outside of the current session\n\n# Use the kagglehub client library to attach Kaggle resources like competitions, datasets, and models to your session\n# Learn more about kagglehub: https://github.com/Kaggle/kagglehub/blob/main/README.md\n\n# ____________________________________________________________________________________________________\n# 1. imports\nimport os\nimport gc\nimport random\n\nimport numpy as np\nimport pandas as pd\n\nimport torch\nfrom torch.utils.data import Dataset, DataLoader\nfrom torch.optim import AdamW\n\nimport kagglehub\n\nfrom kaggle_secrets import UserSecretsClient\n\nfrom sklearn.model_selection import StratifiedKFold\n\nfrom transformers import (\n    AutoTokenizer,\n    AutoModelForSequenceClassification,\n    DataCollatorWithPadding,\n    get_linear_schedule_with_warmup,\n)\n\n# ____________________________________________________________________________________________________\n# 2. Setup\n#2.1 - downlaod competition\nkagglehub.competition_download('smart-mcq-solver-challenge')\n\n# 2.2 - initialize dataframe\n# df = pd.read_csv(\"/kaggle/input/competitions/smart-mcq-solver-challenge/train.csv\")\n\n# 2.3 - SEED (for repeatability)\nSEED = 42\nrandom.seed(SEED)\nnp.random.seed(SEED)\ntorch.manual_seed(SEED)\nif torch.cuda.is_available():\n    torch.cuda.manual_seed_all(SEED)\n\n# 2.4 - Weights and Biases setup\nuser_secrets = UserSecretsClient()\n\n#2.5 - Constants\nBATCH_SIZE = 16\ndevice = torch.device(\n    \"cuda\" if torch.cuda.is_available() else \"cpu\"\n)\nFOLDS = 5\nMODEL_NAME = \"microsoft/deberta-v3-base\"\nSTAGE1_EPOCHS = 8\nSTAGE2_EPOCHS = 5\nMAX_LENGTH = 256\n\n# ____________________________________________________________________________________________________\n# ____________________________________________________________________________________________________\n# ____________________________________________________________________________________________________\n# 3. Functions and Auxilary functional elements\n\n#3.1 - MAP@3 function\n# takes two inputs, one is a list of all correct answers, the other a list of corresponding predictions\ndef map_at_3(y_true, y_pred):\n    score = 0.0\n\n    if len(y_true) != len(y_pred):\n        raise ValueError(\"Length mismatch\")\n\n    for i in range(len(y_true)):\n        pred = y_pred[i]\n        true = y_true[i]\n        if true in pred:\n            for j in range(len(pred)):\n                if pred[j] == true:\n                    score += 1/(j+1)\n                    break\n                \n    return score/len(y_true)\n\n# ____________________________________________________________________________________________________\n# 3.2 - expands dataset \n# takes in a row and creates 5 corresponding rows for each option with whether it is correct or not.\ndef expand_dataset(df):\n    samples = []\n\n    for _, row in df.iterrows():\n        \n        for option in [\"A\",\"B\",\"C\",\"D\",\"E\"]:\n            samples.append({\n                'prompt': row['prompt'],\n\n                'option': row[option],\n    \n                \"question_id\": row[\"id\"]\n            })\n\n    return pd.DataFrame(samples)\n\n# ____________________________________________________________________________________________________\n# 3.3 - MCQDataset Class for making table into an object\n# create MCQDATASET class\nclass MCQDataset(Dataset):\n    def __init__(self, dataframe, tokenizer):\n        self.prompts = dataframe['prompt'].tolist()\n        self.options = dataframe['option'].tolist()\n        self.tokenizer = tokenizer\n\n    def __len__(self):\n        return len(self.prompts)\n\n    def __getitem__(self, idx):\n        encoding = self.tokenizer(\n            self.prompts[idx],\n            self.options[idx],\n            truncation=True,\n            max_length=256\n        )\n\n        return {\n            \"input_ids\":\n                encoding['input_ids'],\n\n            \"attention_mask\":\n                encoding['attention_mask']\n        }\n\n# ____________________________________________________________________________________________________\n# 3.4 - process data to prepare it for training\n# takes in a dataframe and returns dataloader for training\ndef process_data(dataframe, tokenizer, shuffle):\n    expanded_df = expand_dataset(dataframe)\n    data_object = MCQDataset(expanded_df, tokenizer)\n\n    # data collator\n    data_collator = DataCollatorWithPadding(\n        tokenizer=tokenizer,\n        return_tensors=\"pt\"\n    )\n\n    data_loader = DataLoader(\n        data_object,\n        batch_size=BATCH_SIZE,\n        shuffle=shuffle,\n        collate_fn=data_collator,\n        pin_memory=True\n    )\n\n    return data_loader\n\n# ____________________________________________________________________________________________________\n# 3.6 - clean up between stages and folds\ndef clear_data(model):\n    try:\n        del model\n\n        torch.cuda.synchronize()\n        torch.cuda.empty_cache()\n        gc.collect()\n    \n    except Exception as e:\n        return(\"could not clean up model\")\n\n    return\n\n# __________________________________________________________________________________________________________\n# 3.7 - get models\ndef get_model_paths():\n    folds = [1,2,3,5]\n    paths = []\n    for fold in folds:\n        paths.append(f\"/kaggle/input/models/siddharthavarma12/smart-mcq-deberta/pytorch/fold{fold}/1/best_model_fold{fold}_stage2\")\n    return paths\n\n\n# 3.8 - predict for one model\ndef predict_model(\n    test_loader,\n    model\n):\n    model.eval()\n\n    logits = []\n\n    with torch.no_grad():\n        for batch in test_loader:\n            input_ids = batch[\"input_ids\"].to(device)\n\n            attention_mask = batch[\"attention_mask\"].to(device)\n\n            outputs = model(\n\n                input_ids=input_ids,\n\n                attention_mask=attention_mask\n\n            )\n\n            positive_logits = outputs.logits[:,1]\n\n            logits.extend(\n\n                positive_logits.cpu().numpy()\n\n            )\n\n    logits = np.array(logits)\n\n    logits = logits.reshape(-1,5)\n\n    clear_data(model)\n\n    return logits\n\ndef ensemble_predictions(\n    test_loader\n):\n    predictions = []\n    \n    for path in get_model_paths():\n        model = AutoModelForSequenceClassification.from_pretrained(\n            path\n        )\n        model = model.to(device)\n        pred = predict_model(test_loader, model)\n        predictions.append(pred)\n\n    predictions = np.stack(\n        predictions,\n        axis=0\n    )\n\n    predictions = np.mean(\n        predictions,\n        axis=0\n    )\n\n    return predictions\n\ndef create_submission(predictions, df):\n    options = np.array([\n        \"A\",\n\n        \"B\",\n\n        \"C\",\n\n        \"D\",\n\n        \"E\"]\n    )\n\n    final_predictions = []\n\n    for row in predictions:\n        ranking = np.argsort(\n            -row\n        )\n\n        prediction = \" \".join(\n\n            options[ranking[:3]]\n\n        )\n        \n        final_predictions.append(prediction)\n\n    submission = pd.DataFrame({\n        \"id\": df[\"id\"],\n        \"prediction\": final_predictions        \n    })\n\n    submission.to_csv(\n        \"submission.csv\",\n        index=False\n    )\n\n    return submission\n\n# ____________________________________________________________________________________________________\n# ____________________________________________________________________________________________________\n# ____________________________________________________________________________________________________\ndef main():\n    df = pd.read_csv(\"/kaggle/input/competitions/smart-mcq-solver-challenge/test.csv\")\n\n    tokenizer = AutoTokenizer.from_pretrained(MODEL_NAME)\n\n    test_loader = process_data(\n        df,\n        tokenizer,\n        False\n    )\n\n    predictions = ensemble_predictions(test_loader)\n\n    submission = create_submission(\n        predictions,\n        df\n    )\n    submission.head()\n    \nif __name__ == \"__main__\":\n\n    main()","metadata":{"_uuid":"ad78ec9e-af80-4b3c-9996-5d9a951df09d","_cell_guid":"b84acde2-2a4b-42c2-835e-39bfdb8a43f8","trusted":true,"collapsed":false,"jupyter":{"outputs_hidden":false},"execution":{"iopub.status.busy":"2026-07-08T10:22:31.561454Z","iopub.execute_input":"2026-07-08T10:22:31.562408Z","iopub.status.idle":"2026-07-08T10:24:23.886925Z","shell.execute_reply.started":"2026-07-08T10:22:31.562371Z","shell.execute_reply":"2026-07-08T10:24:23.886256Z"}},"outputs":[{"name":"stdout","text":"/kaggle/input/competitions/smart-mcq-solver-challenge/sample_submission.csv\n/kaggle/input/competitions/smart-mcq-solver-challenge/train.csv\n/kaggle/input/competitions/smart-mcq-solver-challenge/test.csv\n/kaggle/input/models/siddharthavarma12/smart-mcq-deberta/pytorch/fold5/1/best_model_fold5_stage2/config.json\n/kaggle/input/models/siddharthavarma12/smart-mcq-deberta/pytorch/fold5/1/best_model_fold5_stage2/tokenizer.json\n/kaggle/input/models/siddharthavarma12/smart-mcq-deberta/pytorch/fold5/1/best_model_fold5_stage2/tokenizer_config.json\n/kaggle/input/models/siddharthavarma12/smart-mcq-deberta/pytorch/fold5/1/best_model_fold5_stage2/model.safetensors\n/kaggle/input/models/siddharthavarma12/smart-mcq-deberta/pytorch/fold1/1/best_model_fold1_stage2/config.json\n/kaggle/input/models/siddharthavarma12/smart-mcq-deberta/pytorch/fold1/1/best_model_fold1_stage2/tokenizer.json\n/kaggle/input/models/siddharthavarma12/smart-mcq-deberta/pytorch/fold1/1/best_model_fold1_stage2/tokenizer_config.json\n/kaggle/input/models/siddharthavarma12/smart-mcq-deberta/pytorch/fold1/1/best_model_fold1_stage2/model.safetensors\n/kaggle/input/models/siddharthavarma12/smart-mcq-deberta/pytorch/fold2/1/best_model_fold2_stage2/config.json\n/kaggle/input/models/siddharthavarma12/smart-mcq-deberta/pytorch/fold2/1/best_model_fold2_stage2/tokenizer.json\n/kaggle/input/models/siddharthavarma12/smart-mcq-deberta/pytorch/fold2/1/best_model_fold2_stage2/tokenizer_config.json\n/kaggle/input/models/siddharthavarma12/smart-mcq-deberta/pytorch/fold2/1/best_model_fold2_stage2/model.safetensors\n/kaggle/input/models/siddharthavarma12/smart-mcq-deberta/pytorch/fold3/1/best_model_fold3_stage2/config.json\n/kaggle/input/models/siddharthavarma12/smart-mcq-deberta/pytorch/fold3/1/best_model_fold3_stage2/tokenizer.json\n/kaggle/input/models/siddharthavarma12/smart-mcq-deberta/pytorch/fold3/1/best_model_fold3_stage2/tokenizer_config.json\n/kaggle/input/models/siddharthavarma12/smart-mcq-deberta/pytorch/fold3/1/best_model_fold3_stage2/model.safetensors\n","output_type":"stream"},{"output_type":"display_data","data":{"text/plain":"Loading weights:   0%|          | 0/202 [00:00<?, ?it/s]","application/vnd.jupyter.widget-view+json":{"version_major":2,"version_minor":0,"model_id":"3530ae84e75a46698f841e9c37550b12"}},"metadata":{}},{"output_type":"display_data","data":{"text/plain":"Loading weights:   0%|          | 0/202 [00:00<?, ?it/s]","application/vnd.jupyter.widget-view+json":{"version_major":2,"version_minor":0,"model_id":"e0a7ea7234dc449398dcf6db29eda7cb"}},"metadata":{}},{"output_type":"display_data","data":{"text/plain":"Loading weights:   0%|          | 0/202 [00:00<?, ?it/s]","application/vnd.jupyter.widget-view+json":{"version_major":2,"version_minor":0,"model_id":"598f0461e02b441d9ed7b4cc86669115"}},"metadata":{}},{"output_type":"display_data","data":{"text/plain":"Loading weights:   0%|          | 0/202 [00:00<?, ?it/s]","application/vnd.jupyter.widget-view+json":{"version_major":2,"version_minor":0,"model_id":"9bcac9925e6e4c5c8e728d81acb14e55"}},"metadata":{}}],"execution_count":4}]}